package io.atlas.modules.pokedex.repository;
import io.atlas.modules.database.DatabaseManager;
import java.util.*;
public final class PokedexRepository {
 public record Progress(int milestone,int caught,int total,java.time.Instant completed){}
 public Progress load(UUID id){try(var p=DatabaseManager.getConnection().prepareStatement("SELECT milestone,caught,total,completed_at FROM pokedex_progress WHERE uuid=?")){p.setObject(1,id);try(var r=p.executeQuery()){return r.next()?new Progress(r.getInt(1),r.getInt(2),r.getInt(3),r.getTimestamp(4)==null?null:r.getTimestamp(4).toInstant()):new Progress(0,0,0,null);}}catch(java.sql.SQLException e){throw new IllegalStateException("Pokédex indisponível",e);}}
 public Progress save(UUID id,String name,int milestone,int caught,int total){try(var p=DatabaseManager.getConnection().prepareStatement("INSERT INTO pokedex_progress(uuid,username,milestone,caught,total,completed_at) VALUES(?,?,?,?,?,CASE WHEN ?=100 THEN now() ELSE NULL END) ON CONFLICT(uuid) DO UPDATE SET username=EXCLUDED.username,milestone=GREATEST(pokedex_progress.milestone,EXCLUDED.milestone),caught=EXCLUDED.caught,total=EXCLUDED.total,completed_at=COALESCE(pokedex_progress.completed_at,EXCLUDED.completed_at),updated_at=now()")){p.setObject(1,id);p.setString(2,name);p.setInt(3,milestone);p.setInt(4,caught);p.setInt(5,total);p.setInt(6,milestone);p.executeUpdate();return load(id);}catch(java.sql.SQLException e){throw new IllegalStateException("Erro ao salvar progressão Pokédex",e);}}
 public List<String> hall(int page){var out=new ArrayList<String>();try(var p=DatabaseManager.getConnection().prepareStatement("SELECT username,caught,total,completed_at FROM pokedex_progress WHERE completed_at IS NOT NULL ORDER BY completed_at,uuid LIMIT 10 OFFSET ?")){p.setInt(1,page*10);try(var r=p.executeQuery()){while(r.next())out.add(r.getString(1)+" • "+r.getInt(2)+"/"+r.getInt(3)+" • "+java.time.format.DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm").withZone(java.time.ZoneId.of("America/Fortaleza")).format(r.getTimestamp(4).toInstant()));}return out;}catch(java.sql.SQLException e){throw new IllegalStateException("Hall indisponível",e);}}
}
